namespace Local36 {
 public class BotProfile {public int UserID;public string Name;public int Level;public bool Sex;public bool Enabled;public string Profile;}
 public class BotPoolSettings {public int PoolSize=50;public int MinHours=3;public int MaxHours=4;}
 public class BotLlmConfig {public int UserID;public bool Enabled;public string BaseUrl;public string Model;public string ApiKey;public string SystemPrompt;public string Secret;public string SecretHeader;public int MaxTokens;}
 public class BotLlmRequest {public int userId;public bool enabled;public string baseUrl;public string model;public string apiKey;public string systemPrompt;public string secret;public string secretHeader="X-API-Secret";public int maxTokens=180;public bool clearKey;public bool clearSecret;}
 public class BotEquipment {public int templateId;public int strength;public int? slot;}
 public class NewBotRequest {public string name;public int level=1;public bool sex=true;public bool enabled=true;public bool randomEquipment=true;public bool hideSuit=true;public BotEquipment[] equipment=new BotEquipment[0];}
 public static class BotCatalog {
  static readonly object Gate=new object();static readonly Random Random=new Random();static readonly byte[] Entropy=Encoding.UTF8.GetBytes("DDTank36.LocalBot.Llm.v1");
  public static void EnsureSchema(){using(var db=Open())using(var c=new SqlCommand(@"IF OBJECT_ID('dbo.Local36_Bots') IS NULL CREATE TABLE dbo.Local36_Bots(UserID int NOT NULL PRIMARY KEY,Level int NOT NULL,Stage nvarchar(30) NOT NULL,Enabled bit NOT NULL DEFAULT 1,Profile nvarchar(max) NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT sysdatetime());
IF OBJECT_ID('dbo.Local36_GM_Audit') IS NULL CREATE TABLE dbo.Local36_GM_Audit(RequestID uniqueidentifier PRIMARY KEY,ReceiverID int NOT NULL,Payload nvarchar(max) NOT NULL,MailIDs nvarchar(max) NOT NULL,CreatedAt datetime2 NOT NULL DEFAULT sysdatetime());
IF OBJECT_ID('dbo.Local36_BotSettings') IS NULL CREATE TABLE dbo.Local36_BotSettings(ID int NOT NULL PRIMARY KEY CHECK(ID=1),PoolSize int NOT NULL,MinHours int NOT NULL,MaxHours int NOT NULL,UpdatedAt datetime2 NOT NULL DEFAULT sysdatetime());
IF NOT EXISTS(SELECT 1 FROM dbo.Local36_BotSettings WHERE ID=1) INSERT dbo.Local36_BotSettings(ID,PoolSize,MinHours,MaxHours) VALUES(1,50,3,4);
IF OBJECT_ID('dbo.Local36_BotLlm') IS NULL CREATE TABLE dbo.Local36_BotLlm(UserID int NOT NULL PRIMARY KEY,Enabled bit NOT NULL DEFAULT 0,BaseUrl nvarchar(500) NOT NULL,Model nvarchar(200) NOT NULL,ApiKeyEncrypted varbinary(max) NULL,SecretEncrypted varbinary(max) NULL,SecretHeader nvarchar(100) NOT NULL DEFAULT 'X-API-Secret',MaxTokens int NOT NULL DEFAULT 180,UpdatedAt datetime2 NOT NULL DEFAULT sysdatetime());
IF COL_LENGTH('dbo.Local36_BotLlm','SystemPrompt') IS NULL ALTER TABLE dbo.Local36_BotLlm ADD SystemPrompt nvarchar(4000) NOT NULL DEFAULT N'';",db))c.ExecuteNonQuery();}
  public static List<BotProfile> ListProfiles(){EnsureSchema();var rows=new List<BotProfile>();using(var db=Open())using(var c=new SqlCommand("SELECT b.UserID,u.NickName,u.Grade,u.Sex,b.Enabled,b.Profile FROM Local36_Bots b JOIN Sys_User_Detail u ON u.UserID=b.UserID WHERE u.IsExist=1 ORDER BY b.UserID",db))using(var r=c.ExecuteReader())while(r.Read())rows.Add(new BotProfile{UserID=r.GetInt32(0),Name=r.GetString(1),Level=r.GetInt32(2),Sex=r.GetBoolean(3),Enabled=r.GetBoolean(4),Profile=r.GetString(5)});return rows;}
  public static BotPoolSettings ReadSettings(){EnsureSchema();using(var db=Open())using(var c=new SqlCommand("SELECT PoolSize,MinHours,MaxHours FROM Local36_BotSettings WHERE ID=1",db))using(var r=c.ExecuteReader()){r.Read();return new BotPoolSettings{PoolSize=r.GetInt32(0),MinHours=r.GetInt32(1),MaxHours=r.GetInt32(2)};}}
  public static void SaveSettings(BotPoolSettings s){if(s.PoolSize!=50||s.MinHours!=3||s.MaxHours!=4)throw new Exception("当前在线池固定50位，每3至4小时轮换");EnsureSchema();using(var db=Open())Exec(db,null,"UPDATE Local36_BotSettings SET PoolSize=@p0,MinHours=@p1,MaxHours=@p2,UpdatedAt=sysdatetime() WHERE ID=1",s.PoolSize,s.MinHours,s.MaxHours);}
  public static BotLlmConfig ReadLlm(int id){EnsureSchema();using(var db=Open())using(var c=new SqlCommand("SELECT Enabled,BaseUrl,Model,ApiKeyEncrypted,SecretEncrypted,SecretHeader,MaxTokens,SystemPrompt FROM Local36_BotLlm WHERE UserID=@id",db)){c.Parameters.AddWithValue("@id",id);using(var r=c.ExecuteReader()){if(!r.Read())return null;return new BotLlmConfig{UserID=id,Enabled=r.GetBoolean(0),BaseUrl=r.GetString(1),Model=r.GetString(2),ApiKey=Decrypt(r.IsDBNull(3)?null:(byte[])r[3]),Secret=Decrypt(r.IsDBNull(4)?null:(byte[])r[4]),SecretHeader=r.GetString(5),MaxTokens=r.GetInt32(6),SystemPrompt=r.GetString(7)};}}}
  public static object LlmPublic(int id){EnsureSchema();using(var db=Open())using(var c=new SqlCommand("SELECT Enabled,BaseUrl,Model,CASE WHEN DATALENGTH(ApiKeyEncrypted)>0 THEN 1 ELSE 0 END,CASE WHEN DATALENGTH(SecretEncrypted)>0 THEN 1 ELSE 0 END,SecretHeader,MaxTokens,SystemPrompt FROM Local36_BotLlm WHERE UserID=@id",db)){c.Parameters.AddWithValue("@id",id);using(var r=c.ExecuteReader()){if(!r.Read())return new{userId=id,enabled=false,baseUrl="",model="",hasKey=false,hasSecret=false,secretHeader="X-API-Secret",maxTokens=180,systemPrompt=""};return new{userId=id,enabled=r.GetBoolean(0),baseUrl=r.GetString(1),model=r.GetString(2),hasKey=r.GetInt32(3)==1,hasSecret=r.GetInt32(4)==1,secretHeader=r.GetString(5),maxTokens=r.GetInt32(6),systemPrompt=r.GetString(7)};}}}
  public static void SaveLlm(BotLlmRequest a){
   EnsureSchema();a.baseUrl=(a.baseUrl??"").Trim();a.model=(a.model??"").Trim();a.systemPrompt=a.systemPrompt??"";if(a.systemPrompt.Length>4000||a.systemPrompt.Contains("\0"))throw new Exception("性格提示词最多4000字，不能含空字符");Uri uri=null;if(a.baseUrl.Length>0&&(!Uri.TryCreate(a.baseUrl,UriKind.Absolute,out uri)||(uri.Scheme!="https"&&uri.Scheme!="http")||!String.IsNullOrEmpty(uri.UserInfo)||!String.IsNullOrEmpty(uri.Query)||!String.IsNullOrEmpty(uri.Fragment)))throw new Exception("模型服务地址须为完整HTTP/HTTPS地址，不含密码、查询参数和锚点");
   if(a.enabled&&uri==null)throw new Exception("启用模型互动前，请填写实际的模型服务地址；灰色示例不是已填写地址。");if(a.enabled&&String.IsNullOrWhiteSpace(a.model))throw new Exception("启用模型互动前，请填写模型名称。");if(uri!=null&&uri.Scheme=="http"&&!uri.IsLoopback)throw new Exception("非本机模型服务须使用HTTPS");if(a.baseUrl.Length>500||a.model.Length>200||a.enabled&&(uri==null||String.IsNullOrWhiteSpace(a.model))||a.maxTokens<32||a.maxTokens>2048)throw new Exception("请检查模型名及回复长度（32至2048）");
   a.secretHeader=String.IsNullOrWhiteSpace(a.secretHeader)?"X-API-Secret":a.secretHeader.Trim();if(!Regex.IsMatch(a.secretHeader,"^[A-Za-z][A-Za-z0-9-]{0,99}$")||new[]{"host","authorization","proxy-authorization","cookie","set-cookie","connection","transfer-encoding","expect"}.Contains(a.secretHeader.ToLowerInvariant())||a.secretHeader.StartsWith("Content-",StringComparison.OrdinalIgnoreCase))throw new Exception("附加密钥请求头不被允许");
   if((a.apiKey??"").Length>8192||(a.secret??"").Length>8192||(a.apiKey??"").IndexOfAny(new[]{'\r','\n'})>=0||(a.secret??"").IndexOfAny(new[]{'\r','\n'})>=0)throw new Exception("密钥格式不正确");
   using(var db=Open())using(var tx=db.BeginTransaction(IsolationLevel.Serializable))try{if(Convert.ToInt32(Scalar(db,tx,"SELECT COUNT(*) FROM Local36_Bots WHERE UserID=@p0",a.userId))!=1)throw new Exception("请选择名册中的人机");
    byte[] key=ReadEncrypted(db,tx,a.userId,"ApiKeyEncrypted"),secret=ReadEncrypted(db,tx,a.userId,"SecretEncrypted");if(a.clearKey)key=null;else if(!String.IsNullOrEmpty(a.apiKey))key=Encrypt(a.apiKey);if(a.clearSecret)secret=null;else if(!String.IsNullOrEmpty(a.secret))secret=Encrypt(a.secret);if(a.enabled&&(key==null||key.Length==0))throw new Exception("启用前请填写API Key");
    using(var c=new SqlCommand("UPDATE Local36_BotLlm SET Enabled=@enabled,BaseUrl=@url,Model=@model,ApiKeyEncrypted=@key,SecretEncrypted=@secret,SecretHeader=@header,MaxTokens=@tokens,SystemPrompt=@prompt,UpdatedAt=sysdatetime() WHERE UserID=@id;IF @@ROWCOUNT=0 INSERT Local36_BotLlm(UserID,Enabled,BaseUrl,Model,ApiKeyEncrypted,SecretEncrypted,SecretHeader,MaxTokens,SystemPrompt) VALUES(@id,@enabled,@url,@model,@key,@secret,@header,@tokens,@prompt)",db,tx)){c.Parameters.AddWithValue("@id",a.userId);c.Parameters.AddWithValue("@enabled",a.enabled);c.Parameters.AddWithValue("@url",a.baseUrl.TrimEnd('/'));c.Parameters.AddWithValue("@model",a.model.Trim());c.Parameters.Add("@key",SqlDbType.VarBinary,-1).Value=(object)key??DBNull.Value;c.Parameters.Add("@secret",SqlDbType.VarBinary,-1).Value=(object)secret??DBNull.Value;c.Parameters.AddWithValue("@header",a.secretHeader);c.Parameters.AddWithValue("@tokens",a.maxTokens);c.Parameters.AddWithValue("@prompt",a.systemPrompt);c.ExecuteNonQuery();}tx.Commit();try{BotMemory36.SavePersona(a.userId,a.systemPrompt);}catch(Exception e){Console.WriteLine("Persona document sync deferred: "+e.GetType().Name);}}catch{if(tx.Connection!=null)tx.Rollback();throw;}
  }
  public static int CreateBot(NewBotRequest a){lock(Gate){EnsureSchema();a.name=(a.name??"").Trim();if(a.name.Length<2||a.name.Length>20||a.name.Contains("人机")||a.name.Any(Char.IsControl))throw new Exception("昵称须为2至20字，不能包含“人机”或控制字符");if(a.level<1||a.level>60)throw new Exception("等级须在1至60之间");if(a.equipment==null)a.equipment=new BotEquipment[0];if(a.equipment.Length>16)throw new Exception("装备数量过多");
   using(var db=Open())using(var tx=db.BeginTransaction(IsolationLevel.Serializable))try{
    if(Convert.ToInt32(Scalar(db,tx,"SELECT COUNT(*) FROM Sys_User_Detail WHERE NickName=@p0 AND IsExist=1",a.name))>0)throw new Exception("角色昵称已存在");int gp=Convert.ToInt32(Scalar(db,tx,"SELECT GP FROM Level WHERE Grade=@p0",a.level));var equips=new Dictionary<int,BotEquipment>();
    if(a.randomEquipment){foreach(int cat in new[]{1,2,3,4,5,6,7,15}){if(cat==15&&a.level<20)continue;int template=Convert.ToInt32(Scalar(db,tx,"SELECT TOP 1 TemplateID FROM Shop_Goods WHERE CategoryID=@p0 AND CanEquip=1 AND Valid=1 AND NeedLevel<=@p1 AND NeedSex IN(0,@p2) AND (@p3=0 OR CanStrengthen=1) AND (@p4='' OR ','+@p4+',' LIKE '%,'+CONVERT(varchar(20),TemplateID)+',%') ORDER BY NEWID()",cat,a.level,a.sex?1:2,(cat==5||cat==7)&&Strength(a.level)>0?1:0,cat==7?(a.level<10?"7001,7002,7003":a.level<25?"7006,7007,7008,7009":a.level<40?"7015,7016,7017,7018":"7024,7026,7027,7032,7045,7046"):""));if(template>0)AddEquipment(db,tx,equips,new BotEquipment{templateId=template,strength=cat==7||cat==5?Strength(a.level):0},a);}}
    foreach(var e in a.equipment)AddEquipment(db,tx,equips,e,a);if(!equips.ContainsKey(6))throw new Exception("需要指定可用武器（类别7）或启用随机装备");
    int id;string username="bot36_custom_"+Guid.NewGuid().ToString("N").Substring(0,16);using(var c=new SqlCommand("SP_Users_Active",db,tx)){c.CommandType=CommandType.StoredProcedure;SqlCommandBuilder.DeriveParameters(c);foreach(SqlParameter p in c.Parameters){if(p.Direction==ParameterDirection.ReturnValue)continue;p.Value=p.SqlDbType==SqlDbType.Bit?(object)false:p.SqlDbType==SqlDbType.Int?(object)0:(object)"";}foreach(string s in new[]{"Attack","Defence","Luck","Agility"})c.Parameters["@"+s].Value=10+a.level*2;c.Parameters["@UserName"].Value=username;c.Parameters["@PassWord"].Value=Guid.NewGuid().ToString("N");c.Parameters["@Sex"].Value=a.sex;c.Parameters["@Grade"].Value=a.level;c.Parameters["@GP"].Value=gp;c.Parameters["@Hide"].Value=a.hideSuit?1111112111:1111111111;c.Parameters["@ActiveIP"].Value="127.0.0.1";c.Parameters["@Gold"].Value=1000000;c.Parameters["@Money"].Value=100000;c.Parameters["@GiftToken"].Value=100000;c.ExecuteNonQuery();if(Convert.ToInt32(c.Parameters["@RETURN_VALUE"].Value)!=0)throw new Exception("原生角色创建失败");id=Convert.ToInt32(c.Parameters["@UserID"].Value);}
    var style=new string[16];foreach(var e in equips){int slot=StyleSlot(e.Key);if(slot<0)continue;string pic=Convert.ToString(Scalar(db,tx,"SELECT Pic FROM Shop_Goods WHERE TemplateID=@p0",e.Value.templateId));style[slot]=e.Value.templateId+"|"+pic;}
    Exec(db,tx,"UPDATE Sys_User_Detail SET NickName=@p0,Grade=@p1,GP=@p2,IsFirst=4,State=0,Hide=@p3,Style=@p4,Colors=',,,,,,,,,,,,,,,',Skin='',IsExist=1 WHERE UserID=@p5",a.name,a.level,gp,a.hideSuit?1111112111:1111111111,String.Join(",",style),id);
    Exec(db,tx,"DELETE Sys_User_Goods WHERE UserID=@p0",id);foreach(var e in equips)Exec(db,tx,"INSERT Sys_User_Goods(UserID,BagType,TemplateID,Place,Count,IsJudge,Color,IsExist,StrengthenLevel,AttackCompose,DefendCompose,LuckCompose,AgilityCompose,IsBinds,BeginDate,ValidDate,IsUsed,Skin) VALUES(@p0,0,@p1,@p2,1,1,'',1,@p3,0,0,0,0,1,GETDATE(),0,1,'')",id,e.Value.templateId,e.Key,e.Value.strength);
    string stage=a.level<10?"新手":a.level<25?"成长":a.level<40?"进阶":"高阶";var profile=new{UserID=id,Username=username,Name=a.name,Level=a.level,Sex=a.sex,Stage=stage,Strength=Strength(a.level),HideSuit=a.hideSuit,Equips=equips.ToDictionary(x=>x.Key.ToString(),x=>x.Value.templateId)};string json=new JavaScriptSerializer().Serialize(profile);Exec(db,tx,"INSERT Local36_Bots(UserID,Level,Stage,Enabled,Profile) VALUES(@p0,@p1,@p2,@p3,@p4)",id,a.level,stage,a.enabled,json);tx.Commit();try{ExportProfiles();}catch(Exception e){Console.WriteLine("Bot roster export deferred: "+e.Message);}return id;
   }catch{if(tx.Connection!=null)tx.Rollback();throw;}
  }}
  public static void EnsureRoster(int target=200){lock(Gate){EnsureSchema();if(target<50||target>1000)throw new Exception("名册数量须在50至1000之间");foreach(var b in ListProfiles()){string nick=b.Name.Replace("人机","");using(var db=Open()){if(Convert.ToInt32(Scalar(db,null,"SELECT COUNT(*) FROM Sys_User_Detail WHERE NickName=@p0 AND UserID<>@p1 AND IsExist=1",nick,b.UserID))>0)nick=nick+b.UserID;var profile=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(b.Profile);profile["Name"]=nick;if(!profile.ContainsKey("HideSuit"))profile["HideSuit"]=true;bool hide=Convert.ToBoolean(profile["HideSuit"]);Exec(db,null,"UPDATE Sys_User_Detail SET NickName=@p0,Hide=@p3 WHERE UserID=@p1;UPDATE Local36_Bots SET Profile=@p2 WHERE UserID=@p1",nick,b.UserID,new JavaScriptSerializer().Serialize(profile),hide?1111112111:1111111111);}}
   using(var db=Open())Exec(db,null,"UPDATE spouse SET SpouseName=own.NickName FROM Sys_User_Detail spouse JOIN Sys_User_Detail own ON own.UserID=spouse.SpouseID JOIN Local36_Bots b ON own.UserID=b.UserID WHERE spouse.SpouseName<>own.NickName");
   string[] first={"听雨","竹影","星澜","云栖","南风","晚晴","白露","浅夏","初霁","月笙","枫眠","海棠","青禾","墨羽","知秋","鹿鸣","清欢","望舒","落樱","长歌"};string[] last={"微光","小溪","行舟","如梦","逐月","拾光","松间","春晓","飞萤","茶语"};int[] levels={1,5,10,15,20,25,30,35,40,45,50,60};int count=ListProfiles().Count;for(int i=count;i<target;i++){string name=first[i%first.Length]+last[(i/first.Length)%last.Length];using(var db=Open())if(Convert.ToInt32(Scalar(db,null,"SELECT COUNT(*) FROM Sys_User_Detail WHERE NickName=@p0 AND IsExist=1",name))>0)name+=i;CreateBot(new NewBotRequest{name=name,level=levels[i%levels.Length],sex=i%2==0,hideSuit=true,randomEquipment=true});}ExportProfiles();}}
  public static void ExportProfiles(){var data=ListProfiles().Select(x=>{var row=(Dictionary<string,object>)new JavaScriptSerializer().DeserializeObject(x.Profile);row["Name"]=x.Name;row["Level"]=x.Level;row["Sex"]=x.Sex;row["Enabled"]=x.Enabled;row["Stage"]=x.Level<10?"新手":x.Level<25?"成长":x.Level<40?"进阶":"高阶";return row;}).ToArray();Directory.CreateDirectory(Path.Combine(Paths36.Root,"config"));string path=Path.Combine(Paths36.Root,"config","bots36.json"),temp=path+".tmp";File.WriteAllText(temp,new JavaScriptSerializer().Serialize(data),new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
  static int Strength(int level){return level<10?0:level<20?3:level<30?6:level<40?8:level<50?10:12;}
  static int StyleSlot(int slot){return slot<=6?slot:slot==11?7:slot==13?8:slot==14?9:slot==15?10:-1;}
  static int EquipSlot(int category){switch(category){case 1:return 0;case 2:return 1;case 3:return 2;case 4:return 3;case 5:return 4;case 6:return 5;case 7:return 6;case 8:return 7;case 9:return 9;case 13:return 11;case 14:return 12;case 15:return 13;case 16:return 14;case 17:return 15;default:return -1;}}
  static void AddEquipment(SqlConnection db,SqlTransaction tx,Dictionary<int,BotEquipment> result,BotEquipment e,NewBotRequest a){e.templateId=StrengthenFamily36.Resolve(e.templateId,e.strength);using(var c=new SqlCommand("SELECT CategoryID,NeedLevel,NeedSex,CanEquip,CanStrengthen FROM Shop_Goods WHERE TemplateID=@id AND Valid=1",db,tx)){c.Parameters.AddWithValue("@id",e.templateId);using(var r=c.ExecuteReader()){if(!r.Read())throw new Exception("装备模板不存在或不可用："+e.templateId);int cat=r.GetInt32(0),slot=e.slot??EquipSlot(cat);bool validSlot=slot==EquipSlot(cat)||(cat==8&&slot==8)||(cat==9&&slot==10);if(!validSlot||slot<0||!r.GetBoolean(3))throw new Exception("模板不能穿戴："+e.templateId);if(r.GetInt32(1)>a.level||r.GetInt32(2)!=0&&r.GetInt32(2)!=(a.sex?1:2))throw new Exception("装备等级或性别要求不符："+e.templateId);if(e.strength<0||e.strength>12||e.strength>0&&!r.GetBoolean(4))throw new Exception("强化等级不被该装备支持："+e.templateId);result[slot]=e;}}}
  static SqlConnection Open(){var c=new SqlConnection(Paths36.Db);c.Open();return c;}
  static object Scalar(SqlConnection db,SqlTransaction tx,string sql,params object[] values){using(var c=Command(db,tx,sql,values))return c.ExecuteScalar();}
  static void Exec(SqlConnection db,SqlTransaction tx,string sql,params object[] values){using(var c=Command(db,tx,sql,values))c.ExecuteNonQuery();}
  static SqlCommand Command(SqlConnection db,SqlTransaction tx,string sql,object[] values){var c=new SqlCommand(sql,db,tx);c.CommandTimeout=60;for(int i=0;i<values.Length;i++)c.Parameters.AddWithValue("@p"+i,values[i]??DBNull.Value);return c;}
  static byte[] ReadEncrypted(SqlConnection db,SqlTransaction tx,int id,string column){object value=Scalar(db,tx,"SELECT "+column+" FROM Local36_BotLlm WHERE UserID=@p0",id);return value==null||value==DBNull.Value?null:(byte[])value;}
  static byte[] Encrypt(string value){return ProtectedData.Protect(Encoding.UTF8.GetBytes(value),Entropy,DataProtectionScope.LocalMachine);}
  static string Decrypt(byte[] value){return value==null?"":Encoding.UTF8.GetString(ProtectedData.Unprotect(value,Entropy,DataProtectionScope.LocalMachine));}
 }
